        sys.stderr.write(f"{prog_base()}: exec {name}: No such file or directory\n")
        sys.stderr.flush()
        return 1, None, False
    except PermissionError:
        name = cmd[0] if not opts.s else (os.environ.get('SHELL') or '/bin/sh')
        sys.stderr.write(f"{prog_base()}: exec {name}: Permission denied\n")
        sys.stderr.flush()
        return 1, None, False
    except OSError as e:
        name = cmd[0] if not opts.s else (os.environ.get('SHELL') or '/bin/sh')
        sys.stderr.write(f"{prog_base()}: exec {name}: {e.strerror or str(e)}\n")
        sys.stderr.flush()
        return 1, None, False
    rc = p.wait()
    status, signum = normalize_status(rc)
    report_status(opts, cmd, status, signum)
    return status, signum, True


def start_persistent(opts, cmd, trigger):
    clear_screen(opts.c)
    env = child_env()
    try:
        if opts.s:
            shell = os.environ.get('SHELL') or '/bin/sh'
            return subprocess.Popen([shell, '-c', cmd[0], trigger], env=env, preexec_fn=os.setsid)
        else:
            return subprocess.Popen(replace_placeholder(cmd, trigger), env=env, preexec_fn=os.setsid)
    except FileNotFoundError:
        name = cmd[0] if not opts.s else (os.environ.get('SHELL') or '/bin/sh')
        sys.stderr.write(f"{prog_base()}: exec {name}: No such file or directory\n")
        sys.stderr.flush()
        return None
    except PermissionError:
        name = cmd[0] if not opts.s else (os.environ.get('SHELL') or '/bin/sh')
        sys.stderr.write(f"{prog_base()}: exec {name}: Permission denied\n")
        sys.stderr.flush()
        return None
    except OSError as e:
        name = cmd[0] if not opts.s else (os.environ.get('SHELL') or '/bin/sh')
        sys.stderr.write(f"{prog_base()}: exec {name}: {e.strerror or str(e)}\n")
        sys.stderr.flush()
        return None


def stop_persistent(p, sig=None):
    if p is None:
        return 0, None
    if p.poll() is None:
        try:
            os.killpg(p.pid, sig or restart_signal())
        except ProcessLookupError:
            pass
        except OSError:
            try:
                p.terminate()
            except Exception:
                pass
    try:
        rc = p.wait(timeout=5)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(p.pid, signal.SIGKILL)
        except Exception:
            try:
                p.kill()
            except Exception:
                pass
        rc = p.wait()
    return normalize_status(rc)


def stat_sig(path):
    try:
        st = os.stat(path)
        if os.path.isdir(path):
            return ('dir', st.st_ino, st.st_mtime_ns, st.st_mode)
        return ('file', st.st_ino, st.st_size, st.st_mtime_ns, st.st_mode)
    except OSError:
        return None


def list_dir(path, include_hidden=False):
    try:
        names = set(os.listdir(path))
    except OSError:
        return None
    if not include_hidden:
        names = {n for n in names if not n.startswith('.')}
    return names


class Watcher:
    def __init__(self, files, opts):
        self.files = list(files)
        self.opts = opts
        self.file_sigs = {p: stat_sig(p) for p in self.files}
        self.include_hidden = opts.d >= 2
        self.dir_entries = {}
        # Directories supplied as input are watched for entry changes.
        for p in self.files:
            try:
                if os.path.isdir(p):
                    self.dir_entries[('self', p)] = list_dir(p, self.include_hidden)
            except OSError:
                pass
        if opts.d >= 1:
            parents = set()
            for p in self.files:
                parent = os.path.dirname(p) or '.'
                parents.add(parent)
            for d in parents:
                self.dir_entries[('parent', d)] = list_dir(d, self.include_hidden)
        self.last_trigger = self.files[0]

    def poll(self):
        # Returns (changed, trigger_path, directory_altered)
        changed = False
        trigger = self.last_trigger
        dir_altered = False
        for p in self.files:
            old = self.file_sigs.get(p)
            new = stat_sig(p)
            if old is None:
                self.file_sigs[p] = new
                continue
            if new is None:
                # Deletions are normally noticed through a directory watch.
                self.file_sigs[p] = new
                continue
            if new != old:
                self.file_sigs[p] = new
                # For directories, content changes are handled below.
                if new[0] != 'dir':
                    changed = True
                    trigger = p
        for key, old in list(self.dir_entries.items()):
            kind, d = key
            new = list_dir(d, self.include_hidden)
            if old is None:
                self.dir_entries[key] = new
                continue
            if new is None:
                self.dir_entries[key] = new
                continue
            if new != old:
                self.dir_entries[key] = new
                added = list(new - old)
                removed = list(old - new)
                changed = True
                dir_altered = True
                if added:
                    trigger = os.path.join(d, sorted(added)[0])
                elif removed:
                    trigger = os.path.join(d, sorted(removed)[0])
        if changed:
            self.last_trigger = trigger
        return changed, trigger, dir_altered


def read_tty_command(fd):
    if fd is None:
        return None
    try:
        r, _, _ = select.select([fd], [], [], 0)
        if not r:
            return None
        data = os.read(fd, 32)
    except Exception:
        return None
    if b'q' in data:
        return 'q'
    if b' ' in data:
        return 'space'
    return None


def event_loop(opts, cmd, files, tty_fd):
    global terminate_requested
    watcher = Watcher(files, opts)
    maybe_create_status_script(opts)
    trigger = files[0]

    if opts.z and not opts.p and not opts.r:
        status, _sig, _ok = run_command(opts, cmd, trigger)
        return status

    child = None
    if not opts.p:
        if opts.r:
            child = start_persistent(opts, cmd, trigger)
            if child is None:
                return 1
        else:
            status, _sig, ok = run_command(opts, cmd, trigger)
            if opts.z:
                return status
            if not ok:
                return status

    while True:
        if terminate_requested:
            if opts.r and child is not None:
                stop_persistent(child)
            return 0

        if opts.r and child is not None:
            rc = child.poll()
            if rc is not None:
                status, signum = normalize_status(rc)
                report_status(opts, cmd, status, signum)
                child = None
                if opts.z:
                    return status

        keycmd = read_tty_command(tty_fd)
        if keycmd == 'q':
            if opts.r and child is not None:
                stop_persistent(child)
            return 0
        manual = (keycmd == 'space')

        changed, trig, dir_altered = watcher.poll()
        if manual:
            changed = True
            trig = watcher.last_trigger or files[0]
            dir_altered = False

        if changed:
            trigger = trig
            if opts.r:
                if child is not None:
                    stop_persistent(child)
                child = start_persistent(opts, cmd, trigger)
                if child is None:
                    return 1
                if opts.z:
                    # In -rz mode continue running until child exits or another event.
                    pass
            else:
                status, _sig, ok = run_command(opts, cmd, trigger)
                if opts.z:
                    return status
                if not ok:
                    return status
            if dir_altered:
                sys.stderr.write(f"{prog_base()}: directory altered\n")
                sys.stderr.flush()
                if opts.r and child is not None:
                    stop_persistent(child)
                return 2

        time.sleep(0.1)


def ev_trace(files):
    if 'EV_TRACE' in os.environ:
        sys.stderr.write(f"open_max: {os.sysconf('SC_OPEN_MAX')}\n")
        sys.stderr.flush()


def main():
    global terminate_requested
    signal.signal(signal.SIGINT, handle_sigint)
    opts, cmd = parse_args(sys.argv)
    files = read_filenames()
    fd, old = setup_tty(opts.n)
    ev_trace(files)
    try:
        rc = event_loop(opts, cmd, files, fd)
    finally:
        restore_tty(fd, old)
    sys.exit(rc)

if __name__ == '__main__':
    main()
